WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='PRUEBAS_ESTATICAS' AND v.numero=1),d(t,o) AS (VALUES('DATOS DE PRUEBA',1),('FRENO DE EMERGENCIA POR PRESIÓN MÍNIMA DE TDP',2),('FRENO DE EMERGENCIA POR AW4',3),('FRENO DE SERVICIO MÁXIMO',4),('FRENO DE EMERGENCIA POR MANIPULADOR',5),('FRENO DE RETENCIÓN',6),('EMERGENCIA POR ACTUACIÓN DE LA SETA DE EMERGENCIA',7),('ESTANQUEIDAD NEUMÁTICA DE LA UNIDAD',8),('LISTA DE INSTRUMENTOS',9),('OBSERVACIONES',10),('PERSONAL',11)) INSERT INTO cartillas.secciones(version_id,titulo,orden) SELECT v.id,d.t,d.o FROM v CROSS JOIN d ON CONFLICT(version_id,orden) DO UPDATE SET titulo=EXCLUDED.titulo,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='PRUEBAS_ESTATICAS' AND v.numero=1),s AS (SELECT id,titulo FROM cartillas.secciones WHERE version_id=(SELECT id FROM v)),d(t,c,e,ty,o,cf) AS (VALUES('DATOS DE PRUEBA','tren','TREN N°:','texto',1,'{}'),('DATOS DE PRUEBA','fecha','Fecha de Prueba :','fecha',2,'{}'),('FRENO DE EMERGENCIA POR PRESIÓN MÍNIMA DE TDP','resultado_tdp','Resultado TDP','tabla',1,'{"columnas":[{"codigo":"coche","etiqueta":"COCHE"},{"codigo":"resultado","etiqueta":"√ / X"}],"filasIniciales":[{"coche":"MA1"},{"coche":"MB1"},{"coche":"R"},{"coche":"MB2"},{"coche":"MA2"}]}'),('FRENO DE EMERGENCIA POR AW4','resultado_aw4','Resultado AW4','tabla',1,'{"columnas":[{"codigo":"resultado","etiqueta":"√ / X"}],"filasIniciales":[{}]}'),('FRENO DE SERVICIO MÁXIMO','servicio_maximo','FRENO DE SERVICIO MÁXIMO','tabla',1,'{"columnas":[{"codigo":"coche","etiqueta":"COCHE"},{"codigo":"teorico","etiqueta":"VALOR TEÓRICO"},{"codigo":"visualizado","etiqueta":"Valor visualizado"}],"filasIniciales":[{"coche":"Ma1, Ma2","teorico":"1,8 (+/- 0,2) Bares"},{"coche":"Mb1, Mb2","teorico":"1,8 (+/- 0,2) Bares"},{"coche":"R","teorico":"1,8 (+/- 0,2) Bares"}]}'),('FRENO DE EMERGENCIA POR MANIPULADOR','manipulador','FRENO DE EMERGENCIA POR MANIPULADOR','tabla',1,'{"columnas":[{"codigo":"coche","etiqueta":"COCHE"},{"codigo":"teorico","etiqueta":"VALOR TEÓRICO"},{"codigo":"visualizado","etiqueta":"Valor visualizado"}],"filasIniciales":[{"coche":"Ma1 - Ma2","teorico":"2,2 (+/- 0,2) Bares"},{"coche":"Mb1 - Mb2","teorico":"2,2 (+/- 0,2) Bares"},{"coche":"R","teorico":"1,9 (+/- 0,2) Bares"}]}'),('FRENO DE RETENCIÓN','retencion','FRENO DE RETENCIÓN','tabla',1,'{"columnas":[{"codigo":"coche","etiqueta":"COCHE"},{"codigo":"teorico","etiqueta":"VALOR TEÓRICO"},{"codigo":"visualizado","etiqueta":"Valor visualizado"}],"filasIniciales":[{"coche":"Ma1 - Ma2","teorico":"0,9 (+/- 0,2) Bares"},{"coche":"Mb1 - Mb2","teorico":"0,9 (+/- 0,2) Bares"},{"coche":"R","teorico":"0,9 (+/- 0,2) Bares"}]}'),('EMERGENCIA POR ACTUACIÓN DE LA SETA DE EMERGENCIA','seta','EMERGENCIA POR SETA','tabla',1,'{"columnas":[{"codigo":"coche","etiqueta":"COCHE"},{"codigo":"teorico","etiqueta":"VALOR TEÓRICO"},{"codigo":"visualizado","etiqueta":"Valor visualizado"}],"filasIniciales":[{"coche":"Ma1 - Ma2","teorico":"2,2 (+/- 0,2) Bares"},{"coche":"Mb1 - Mb2","teorico":"2,2 (+/- 0,2) Bares"},{"coche":"R","teorico":"1,9 (+/- 0,2) Bares"}]}'),('ESTANQUEIDAD NEUMÁTICA DE LA UNIDAD','estanqueidad','ESTANQUEIDAD NEUMÁTICA','tabla',1,'{"columnas":[{"codigo":"valor_inicial","etiqueta":"Valor inicial"},{"codigo":"valor_final","etiqueta":"Valor final"},{"codigo":"criterio","etiqueta":"Criterio"}],"filasIniciales":[{"criterio":"Pérdida de presión < 0,6 bar tras 20 min"}]}')) INSERT INTO cartillas.campos(seccion_id,codigo,etiqueta,tipo,orden,configuracion) SELECT s.id,d.c,d.e,d.ty,d.o,d.cf::jsonb FROM d JOIN s ON s.titulo=d.t ON CONFLICT(seccion_id,codigo) DO UPDATE SET configuracion=EXCLUDED.configuracion,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
